(72, 1, 'admin@metamart.local', 'create', 'product', 34, NULL, '{\"id\": 34, \"sku\": \"MEN-TEE-MTB4QB6N\", \"name\": \"Long Sleeve Rib Tee\", \"slug\": \"long-sleeve-rib-tee\", \"badge\": null, \"brand\": \"NORTHLINE\", \"stock\": 19, \"rating\": null, \"status\": \"active\", \"colorway\": \"charcoal\", \"currency\": \"USD\", \"material\": \"ribbed cotton\", \"space_id\": 2, \"created_at\": \"2026-08-27T06:16:12.000Z\", \"created_by\": 1, \"slot_index\": 1, \"updated_at\": \"2026-08-27T06:16:12.000Z\", \"category_id\": 21, \"description\": \"A slim ribbed long sleeve in deep charcoal. Layers flat under knitwear and looks deliberate on its own.\", \"price_cents\": 5600, \"review_count\": 0, \"ai_fields_json\": null, \"attributes_json\": null, \"short_description\": \"Ribbed cotton that hugs the arms and stays put under a jacket.\", \"compare_at_price_cents\": null}', '::1', '2026-08-27 06:16:18'),
