(151, 1, 'admin@metamart.local', 'update', 'space', 2, '{\"id\": 2, \"name\": \"Men\'s Wear\", \"slug\": \"menswear\", \"status\": \"live\", \"tagline\": \"Everyday tailoring and weekend layers.\", \"bay_index\": 0, \"created_at\": \"2026-08-26T18:50:37.000Z\", \"sort_order\": 1, \"updated_at\": \"2026-08-27T06:15:52.000Z\", \"description\": \"Six walls of wardrobe staples: tees and shirts you will wear to death, outerwear that earns its keep, and trousers cut for real legs.\", \"accent_color\": \"#4cc9f0\", \"architecture_id\": 1}', '{\"id\": 2, \"name\": \"Men\'s Wear\", \"slug\": \"menswear\", \"status\": \"live\", \"tagline\": \"Shirts, shoes and the things that finish them.\", \"bay_index\": 0, \"created_at\": \"2026-08-26T18:50:37.000Z\", \"sort_order\": 1, \"updated_at\": \"2026-08-27T09:46:48.000Z\", \"description\": \"Four walls of everyday menswear: shirts you will actually reach for, trainers with some history, and the watches and shades that finish a fit.\", \"accent_color\": \"#4cc9f0\", \"architecture_id\": 1}', '::1', '2026-08-27 09:46:48'),
